from ipaddress import IPv4Address, IPv4Network


def _principal_matches(pattern: str, principal: str, groups: list[str]) -> bool:
    if pattern == "*":
        return True

    kind, _, name = pattern.partition(":")
    if kind == "user":
        return principal.startswith("user:") if name == "*" else principal == pattern
    if kind == "group":
        return bool(groups) if name == "*" else name in groups
    return False


def _action_matches(pattern: str, action: str) -> bool:
    if pattern == "*":
        return True

    pattern_service, pattern_verb = pattern.split(":", 1)
    service, verb = action.split(":", 1)
    return (
        (pattern_service == "*" or pattern_service == service)
        and (pattern_verb == "*" or pattern_verb == verb)
    )


def _resource_matches(pattern: str, resource: str) -> bool:
    pattern_parts = pattern.split("/")
    resource_parts = resource.split("/")
    count = len(resource_parts)

    # previous[j]: the pattern prefix processed so far matches exactly
    # the first j resource segments.
    previous = [False] * (count + 1)
    previous[0] = True

    for segment in pattern_parts:
        current = [False] * (count + 1)

        if segment == "**":
            current[0] = previous[0]
            for j in range(1, count + 1):
                # Match zero segments, or extend this ** by one segment.
                current[j] = previous[j] or current[j - 1]
        else:
            for j in range(1, count + 1):
                current[j] = previous[j - 1] and (
                    segment == "*" or segment == resource_parts[j - 1]
                )

        previous = current

    return previous[count]


def _minutes(value: str) -> int:
    hour, minute = value.split(":")
    return int(hour) * 60 + int(minute)


def _attr_equal(actual, expected) -> bool:
    # Python treats bool as a subclass of int; the policy language does not
    # permit equality between a bool and a non-bool int.
    if (
        isinstance(actual, int)
        and isinstance(expected, int)
        and isinstance(actual, bool) != isinstance(expected, bool)
    ):
        return False
    return actual == expected


def _conditions_match(conditions: dict, attrs: dict) -> bool:
    if "ip_in" in conditions:
        if "ip" not in attrs:
            return False
        address = IPv4Address(attrs["ip"])
        if not any(
            address in IPv4Network(network, strict=False)
            for network in conditions["ip_in"]
        ):
            return False

    if "mfa" in conditions:
        if attrs.get("mfa", False) != conditions["mfa"]:
            return False

    if "time_between" in conditions:
        if "time" not in attrs:
            return False

        start_text, end_text = conditions["time_between"]
        start = _minutes(start_text)
        end = _minutes(end_text)
        time = _minutes(attrs["time"])

        if start < end:
            if not start <= time < end:
                return False
        elif start > end:
            if not (time >= start or time < end):
                return False
        # Equal endpoints match every present time.

    if "weekdays" in conditions:
        if "weekday" not in attrs or attrs["weekday"] not in conditions["weekdays"]:
            return False

    if "tags_any" in conditions:
        tags = attrs.get("tags", [])
        if not any(tag in tags for tag in conditions["tags_any"]):
            return False

    if "tags_all" in conditions:
        tags = attrs.get("tags", [])
        if not all(tag in tags for tag in conditions["tags_all"]):
            return False

    if "attr_equals" in conditions:
        for key, expected in conditions["attr_equals"].items():
            if key not in attrs or not _attr_equal(attrs[key], expected):
                return False

    return True


def evaluate(policies: list[dict], request: dict) -> dict:
    principal = request["principal"]
    groups = request["groups"]
    action = request["action"]
    resource = request["resource"]
    attrs = request["attrs"]

    matching = [
        policy
        for policy in policies
        if any(
            _principal_matches(pattern, principal, groups)
            for pattern in policy["principals"]
        )
        and any(
            _action_matches(pattern, action)
            for pattern in policy["actions"]
        )
        and any(
            _resource_matches(pattern, resource)
            for pattern in policy["resources"]
        )
        and _conditions_match(policy.get("conditions", {}), attrs)
    ]

    # Preserve the original matches, including any overridden denies.
    matched_ids = sorted(policy["id"] for policy in matching)

    overridden = False
    if attrs.get("emergency", False) is True:
        remaining = [
            policy
            for policy in matching
            if not (
                policy["effect"] == "deny"
                and not policy.get("hard", False)
            )
        ]
        overridden = len(remaining) != len(matching)
        matching = remaining

    if not matching:
        return {
            "decision": "deny",
            "policy": None,
            "reason": "no-match",
            "obligations": [],
            "matched": matched_ids,
        }

    winner = min(
        matching,
        key=lambda policy: (
            -policy.get("priority", 0),
            0 if policy["effect"] == "deny" else 1,
            policy["id"],
        ),
    )

    decision = winner["effect"]
    reason = "emergency" if decision == "allow" and overridden else "explicit"

    obligations = set()
    if decision == "allow":
        winning_priority = winner.get("priority", 0)
        for policy in matching:
            if (
                policy["effect"] == "allow"
                and policy.get("priority", 0) == winning_priority
            ):
                obligations.update(policy.get("obligations", []))

        if reason == "emergency":
            obligations.add("audit")

    return {
        "decision": decision,
        "policy": winner["id"],
        "reason": reason,
        "obligations": sorted(obligations),
        "matched": matched_ids,
    }
